function drawMap(){let size=w<700?135:190,x=w-size-20,y=w<700?160:185,pad=16,m=Math.min((size-2*pad)/(bounds.maxX-bounds.minX),(size-2*pad)/(bounds.maxY-bounds.minY)),px=p=>x+size/2+(p.x-(bounds.minX+bounds.maxX)/2)*m,py=p=>y+size/2+(p.y-(bounds.minY+bounds.maxY)/2)*m;ctx.save();ctx.fillStyle='#0b1524e8';ctx.strokeStyle='#344b5a';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(x,y,size,size,12);ctx.fill();ctx.stroke();ctx.fillStyle='#92a9bd';ctx.font='11px sans-serif';ctx.fillText('路线预览',x+12,y-9);ctx.beginPath();mapPoints.forEach((p,i)=>i?ctx.lineTo(px(p),py(p)):ctx.moveTo(px(p),py(p)));ctx.strokeStyle='#557487';ctx.lineWidth=4;ctx.stroke();let g=gates[Math.min(nextGate,gates.length-1)];ctx.beginPath();ctx.moveTo(px(car),py(car));ctx.lineTo(px(g),py(g));ctx.strokeStyle='#b5ff64';ctx.lineWidth=2;ctx.stroke();for(const [p,color]of [[road[0],'#65ddff'],[mapPoints[mapPoints.length-1],'#ffcf68']]){ctx.fillStyle=color;ctx.fillRect(px(p)-3,py(p)-3,6,6)}ctx.translate(px(car),py(car));ctx.rotate(car.a);ctx.fillStyle='#b7ff65';ctx.beginPath();ctx.moveTo(7,0);ctx.lineTo(-5,-4);ctx.lineTo(-5,4);ctx.closePath();ctx.fill();ctx.restore()}
