let physicsAccumulator=0;function loop(t){let dt=Math.max(0,Math.min((t-last)/1000,.1));last=t;if(mode==='race'){physicsAccumulator+=dt;while(physicsAccumulator>=1/120&&mode==='race'){update(1/120);physicsAccumulator-=1/120}}else physicsAccumulator=0;draw(t);requestAnimationFrame(loop)}
function start(){resetCar();mode='race';$('menu').hidden=true;$('hud').hidden=false;$('overlay').hidden=true;$('trackName').textContent=`0${selected+1} / ${circuits[selected].name} · ★★★ ${circuits[selected].three.toFixed(2)}s`;$('pause').textContent='暂停'}
function finish(win){mode='result';joy=null;keys={};if(gain)gain.gain.value=0;const c=circuits[selected],stars=win?(elapsed<=c.three?3:elapsed<=c.two?2:1):0,earned=Math.max(0,stars-save.best[selected])*20+(win?10:0);save.coins+=earned;save.best[selected]=Math.max(save.best[selected],stars);if(win)save.times[selected]=Math.min(save.times[selected]||Infinity,elapsed);persist();menuTracks();$('resultLabel').textContent=win?'CIRCUIT COMPLETE':'TIME IS UP';$('resultTitle').textContent=win?'漂亮的过弯。':'再试一次。';$('resultBody').innerHTML=`<div class="bigStars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><div class="resultStat">本次用时<b>${elapsed.toFixed(2)} 秒</b></div><div class="resultStat">时钟补给<b>${clockCount} 个 / +${clockBonus.toFixed(1)} 秒</b></div><div class="resultStat">金币奖励<b>+${earned}</b></div><div class="resultStat">三星目标<b>${c.three} 秒以内</b></div><p>${win?'时钟延长生存倒计时；三星按实际驾驶用时评定。完赛奖励 10 金币。':'试着提前转向；偏离赛道会降低速度。'}</p>`;$('overlay').hidden=false;$('continue').textContent='再次挑战'}
function home(){mode='menu';joy=null;keys={};$('menu').hidden=false;$('hud').hidden=true;$('overlay').hidden=true;if(gain)gain.gain.value=0;resetCar();menuTracks()}
$('start').onclick=start;$('restart').onclick=start;$('pause').onclick=()=>{if(mode!=='race')return;mode='paused';joy=null;keys={};if(gain)gain.gain.value=0;$('resultLabel').textContent='TAKE A BREATH';$('resultTitle').textContent='休息一下';$('resultBody').innerHTML='<p>赛道会等你。准备好后继续驾驶。</p>';$('continue').textContent='继续驾驶';$('overlay').hidden=false};$('continue').onclick=()=>{if(mode==='paused'){mode='race';$('overlay').hidden=true}else start()};$('back').onclick=home;
function shop(){const items=category==='body'?paints:category==='tire'?tireSkins:trailSkins,owned=category==='body'?save.owned:category==='tire'?save.tiresOwned:save.trailsOwned,equipped=category==='body'?save.skin:save[category];$('skins').innerHTML='<div class="garageTabs">'+[['body','车身'],['tire','轮胎印'],['trail','拖尾']].map(([id,name])=>`<button data-category="${id}" class="${category===id?'chosen':''}">${name}</button>`).join('')+'</div><div class="skinList">'+items.map((p,i)=>`<div class="skin"><span><i style="background:${p.color==='rainbow'?'linear-gradient(90deg,#ff639d,#ffdf68,#65ffe3,#b994ff)':p.color==='body'?paints[save.skin].color:p.color};color:${p.color}"></i>${p.name}</span><button data-skin="${i}">${equipped===i?'已装备':owned.includes(i)?'装备':p.price+' 金币'}</button></div>`).join('')+'</div>';document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;shop()});document.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{let i=+b.dataset.skin;if(!owned.includes(i)){if(save.coins<items[i].price){toast('金币不足，完成比赛获取金币');return}save.coins-=items[i].price;owned.push(i)}if(category==='body')save.skin=i;else save[category]=i;persist();menuTracks();shop()})}
$('shopBtn').onclick=()=>{shop();$('garage').hidden=false};$('closeShop').onclick=()=>{$('garage').hidden=true};
canvas.addEventListener('pointerdown',e=>{if(mode!=='race'||joy)return;canvas.setPointerCapture(e.pointerId);joy={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0}});canvas.addEventListener('pointermove',e=>{if(!joy||e.pointerId!==joy.id)return;let dx=e.clientX-joy.x,dy=e.clientY-joy.y,len=Math.hypot(dx,dy),ratio=Math.min(1,65/(len||1));joy.dx=dx*ratio;joy.dy=dy*ratio});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{if(joy?.id===e.pointerId)joy=null});addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key.length===1?e.key.toLowerCase():e.key]=true;if(e.key==='Escape'&&mode==='race')$('pause').click()});addEventListener('keyup',e=>keys[e.key.length===1?e.key.toLowerCase():e.key]=false);addEventListener('blur',()=>{if(mode==='race')$('pause').click();keys={};joy=null});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='race')$('pause').click()});
$('sound').onclick=()=>{try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();osc=audio.createOscillator();gain=audio.createGain();osc.type='sawtooth';gain.gain.value=0;osc.connect(gain);gain.connect(audio.destination);osc.start()}audio.resume();soundOn=!soundOn;$('sound').textContent='音效 '+(soundOn?'开':'关');if(!soundOn)gain.gain.value=0}catch{toast('当前浏览器暂不支持音效')}};addEventListener('resize',resize);buildTrack();resetCar();resize();menuTracks();requestAnimationFrame(loop);
